/* Declarative presets: no executable code is loaded from component packs. */
(function(root){'use strict';
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k),copy=o=>JSON.parse(JSON.stringify(o));
const fail=s=>{throw Error(s)},obj=o=>o&&typeof o==='object'&&!Array.isArray(o),safeId=x=>typeof x==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(x)&&!['constructor','prototype','__proto__'].includes(x);
function safeTree(o,depth=0){if(depth>12)fail('器件包嵌套过深');if(!o||typeof o!=='object')return;for(const k of Object.keys(o)){if(['__proto__','prototype','constructor'].includes(k))fail('非法字段：'+k);safeTree(o[k],depth+1)}}
function pose(p={},label='pose'){if(!obj(p))fail(label+' 应为对象');for(const [k,v]of Object.entries(p)){if(!['x','y','z','yaw','pitch','roll'].includes(k)||typeof v!=='number'||!Number.isFinite(v)||Math.abs(v)>1e6)fail(label+' 无效坐标或角度：'+k);if(k==='z'&&v<0||k==='pitch'&&Math.abs(v)>90)fail(label+' 超出范围：'+k)}return copy(p)}
function params(p,base){if(!obj(p))fail('params 应为对象');for(const [k,v]of Object.entries(p)){if(!own(base,k))fail('未知模型参数：'+k);if(typeof v!==typeof base[k]||typeof v==='number'&&!Number.isFinite(v))fail('参数类型错误：'+k);if(typeof v==='number'){
 if(['dutyCycle','transmission','reflectivity','reflection','passTransmission','blockTransmission'].includes(k)&&(v<0||v>100))fail(k+' 必须在 0–100%');
 if(['power','thickness','opticalDensity','travel','targetDelay','responsivity','transimpedanceGain','saturationPower'].includes(k)&&v<0)fail(k+' 不能为负');
 if(['aperture','wavelength','repetitionRate','waistRadius','pulseWidth','refractiveIndex','groupIndex','minWavelength','maxWavelength','cutoffWavelength','centerWavelength','bandwidth','scanStep'].includes(k)&&v<=0)fail(k+' 必须为正');
 if(k==='separationAngle'&&(v<=0||v>=90))fail(k+' 必须大于 0 且小于 90°');
 if(k==='m2'&&v<1||k==='ellipticity'&&Math.abs(v)>45||k==='focalLength'&&v===0)fail(k+' 超出模型范围');
 }if(k==='interaction'&&!['transmit','reflect','both'].includes(v)||k==='filterType'&&!['shortpass','longpass','bandpass'].includes(v)||k==='reflectBand'&&!['short','long'].includes(v))fail('不支持的枚举值：'+k)}return copy(p)}
function validate(input,defs){
 safeTree(input);if(!obj(input)||input.kind!=='optical-bench-components'||input.version!==1)fail('不是 version 1 的 optical-bench-components 器件包');
 if(!safeId(input.id))fail('器件包 id 必须以字母开头，只含字母数字、下划线和短横线');
 if(!Array.isArray(input.templates)||!input.templates.length||input.templates.length>50)fail('器件包需要 1–50 个模板');
 const ids=new Set(),templates=input.templates.map(t=>{if(!obj(t)||!safeId(t.id)||ids.has(t.id))fail('模板 id 缺失、非法或重复');ids.add(t.id);if(!own(defs,t.baseType))fail('未知物理模型：'+t.baseType);if(typeof t.name!=='string'||!t.name.trim()||t.name.length>100)fail('模板名称需要 1–100 个字符');const p=params(t.params||{},defs[t.baseType].defaults);const merged={...defs[t.baseType].defaults,...p};if(merged.minWavelength>merged.maxWavelength)fail('探测器波长范围颠倒');return{id:t.id,name:t.name,baseType:t.baseType,params:p,pose:pose(t.pose||{}),notes:String(t.notes||'').slice(0,2000)}});
 const placements=input.placements||[];if(!Array.isArray(placements)||placements.length>200)fail('最多 200 个放置位置');
 return{version:1,kind:'optical-bench-components',id:input.id,name:String(input.name||input.id).slice(0,100),notes:String(input.notes||'').slice(0,4000),templates,placements:placements.map(p=>{if(!obj(p)||!ids.has(p.template))fail('放置引用不存在的模板');return{template:p.template,pose:pose(p.pose||{}),name:String(p.name||'').slice(0,100)}})};
}
function instantiate(input,defs,existing=[]){const pack=validate(input,defs),ids=new Set(existing.map(c=>c.id));const placements=pack.placements.length?pack.placements:pack.templates.map(t=>({template:t.id,pose:{}}));return placements.map((p,i)=>{const t=pack.templates.find(t=>t.id===p.template);let id=pack.id+'-'+t.id,n=1;while(ids.has(id))id=pack.id+'-'+t.id+'-'+n++;ids.add(id);return{id,type:t.baseType,name:p.name||t.name,x:100+i*50,y:100,z:100,yaw:0,pitch:0,roll:0,...t.pose,...p.pose,params:{...defs[t.baseType].defaults,...t.params},componentTemplate:{packId:pack.id,templateId:t.id,notes:t.notes}}})}
const example={version:1,kind:'optical-bench-components',id:'lab-presets',name:'实验室常用器件',notes:'示例参数，不代表厂商实测曲线。',templates:[{id:'od3',name:'ND · OD3',baseType:'nd',params:{opticalDensity:3}},{id:'sp775',name:'SP · 775 nm',baseType:'spectralFilter',params:{filterType:'shortpass',cutoffWavelength:775,passTransmission:90,blockTransmission:0.01}}]};
const api={validate,instantiate,example};root.ComponentPacks=api;if(typeof module!=='undefined')module.exports=api;
if(!root.document||!root.OpticalBench)return;
const app=root.OpticalBench,defs=root.OPTICAL_COMPONENTS,$=id=>document.getElementById(id);
let panel=null;
function refresh(){let holder=$('customComponentCards');if(!holder){holder=document.createElement('div');holder.id='customComponentCards';$('componentLibrary')?.after(holder)}holder.replaceChildren();const packs=app.exportDesign().componentPacks||[];
 for(const raw of packs){let p;try{p=validate(raw,defs)}catch(e){const message=document.createElement('p');message.textContent='器件包无法加载：'+e.message;holder.append(message);continue}
  for(const t of p.templates){const b=document.createElement('button');b.className='component-card';b.textContent='＋ '+t.name;b.title='基于 '+defs[t.baseType].name+'；'+t.notes;b.onclick=()=>{if(root.experimentLocked)return;const s=app.exportDesign(),board=s.boards[0];const one={...p,templates:[t],placements:[{template:t.id,pose:{x:board.x+4*board.spacing,y:board.y+4*board.spacing,...t.pose}}]};app.insertComponents(instantiate(one,defs,s.components))};holder.append(b)}
 }
}
function open(){if(root.experimentLocked)return;if(!panel){panel=document.createElement('section');panel.id='componentPackPanel';panel.setAttribute('aria-label','AI 器件包');panel.style.cssText='position:fixed;inset:8vh 10vw;z-index:90;background:white;border:1px solid #abc;border-radius:12px;padding:24px;overflow:auto;box-shadow:0 20px 90px #3455';panel.innerHTML='<h2>AI 器件包</h2><p>告诉 AI 你需要的器件名称、作用、参数与放置位置，再导入生成的 JSON。此入口复用现有物理模型；新物理行为需由 AI 修改并验证软件代码。</p><input id="packFile" type="file" accept=".json"><button id="packExample">填入示例</button><textarea id="packText" rows="14" style="display:block;width:100%;margin:12px 0;font-family:monospace" aria-label="器件包 JSON"></textarea><label><input id="packPlace" type="checkbox" checked> 导入后自动放入光路（可撤销）</label><p id="packStatus" role="status"></p><button id="packImport">导入器件包</button> <button id="packClose">关闭</button>';document.body.append(panel);panel.addEventListener('keydown',e=>e.stopPropagation());$('packClose').onclick=()=>panel.hidden=true;$('packExample').onclick=()=>$('packText').value=JSON.stringify(example,null,2);$('packFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>250000)fail('器件包最大 250 KB');$('packText').value=await f.text();$('packStatus').textContent='已读取，请检查后导入'}catch(err){$('packStatus').textContent=err.message}e.target.value=''};
 $('packImport').onclick=()=>{try{if($('packText').value.length>250000)fail('器件包最大 250 KB');const pack=validate(JSON.parse($('packText').value),defs),s=app.exportDesign(),packs=s.componentPacks||[];if(packs.some(p=>p.id===pack.id))fail('同名器件包已存在；请使用新的包 id');if(packs.length>=20)fail('最多保存 20 个器件包');const items=$('packPlace').checked?instantiate(pack,defs,s.components):[];if(items.length)app.insertComponents(items);app.setComponentPacks([...packs,pack]);refresh();$('packStatus').textContent='已加入器件库'+(items.length?'，已放置 '+items.length+' 个器件':'')+'。保存设计 JSON 可一同分享。'}catch(e){$('packStatus').textContent=e.message}};
 }panel.hidden=false;}
api.refresh=refresh;api.open=open;const trigger=$('componentPackBtn');if(trigger)trigger.onclick=open;refresh();
})(typeof window!=='undefined'?window:globalThis);
